    // CSRF validation logic
    const expectedOrigin = `https://${req.headers.host}`;
    const actualOrigin = req.headers.origin;

    if (actualOrigin !== expectedOrigin) {
      console.error("CSRF validation failed: Origin mismatch.");
      return res.status(403).json({ error: "CSRF validation failed." });
    }

    // ... rest of the code for creating a referral ...
