// src/api/referrals/route.ts
import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { createReferralSchema } from "@/schema/referral";
import { generateReferralCode } from "@/utils/referral";

export async function POST(req: NextRequest) {
    try {
        const body = await req.json();
        const validatedData = createReferralSchema.parse(body);

        const { name, email, referredByCode } = validatedData;

        // Check if the referrer exists
        const referrer = await prisma.referral.findFirst({
            where: { code: referredByCode },
        });

        if (!referrer) {
            return NextResponse.json({ error: "Invalid referral code" }, { status: 400 });
        }

        // Generate a new unique referral code for the new referral
        let newCode = generateReferralCode();
        const existingReferral = await prisma.referral.findFirst({
            where: { code: newCode },
        });

        while (existingReferral) {
            newCode = generateReferralCode();
            existingReferral = await prisma.referral.findFirst({ where: { code: newCode } });
        }

        // Create the new referral in the database
        const newReferral = await prisma.referral.create({
            data: {
                name,
                email,
                code: newCode,
                referredBy: referrer.id,
            },
        });

        return NextResponse.json(newReferral, { status: 201 });
    } catch (error) {
        console.error("Error creating referral:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}
```

