### 2. DAL Checks

Even after passing the middleware, the application performs Data Access Layer (DAL) checks to ensure that the user is authorized to perform a specific action on a particular resource.

#### a. `src/controllers/user.controller.ts`

This file contains the route handlers that interact with the database and perform authorization checks.

**File:** `src/controllers/user.controller.ts`
**Lines:** 12-14, 19-21, 26-28, 33-35**

```typescript
import { Request, Response } = express;
import { User } from '../models/user.model';
import { AppError, handleError } from '../utils/error.util';

export class UserController {
  // Retrieve all users (only for ADMIN)
  static getAllUsers(req: Request, res: Response) {
    try {
      if (req.user.role !== 'ADMIN') {
        throw new AppError('Forbidden', 403);
      }
      const users = User.findAll();
      res.json(users);
    } catch (error) {
      handleError(error, res);
    }
  }

  // Retrieve a single user by ID (for ADMIN and the user themselves)
  static getUserById(req: Request, res: Response) {
    try {
      const userId = parseInt(req.params.id, 10);
      const currentUser = req.user;

      const user = User.findByPk(userId);

      if (!user) {
        throw new AppError('User not found', 404);
      }

      if (currentUser.role === 'USER' && currentUser.id !== userId) {
        throw new AppError('Forbidden', 403);
      }

      res.json(user);
    } catch (error) {
      handleError(error, res);
    }
  }

  // Update a user (only for ADMIN)
  static updateUser(req: Request, res: Response) {
    try {
      const userId = parseInt(req.params.id, 10);
      const currentUser = req.user;

      if (currentUser.role !== 'ADMIN') {
        throw new AppError('Forbidden', 403);
      }

      const user = User.findByPk(userId);

      if (!user) {
        throw new AppError('User not found', 404);
      }

      // Update user fields
      user.name = req.body.name;
      user.email = req.body.email;
      user.role = req.body.role;
      user.save();

      res.json(user);
    } catch (error) {
      handleError(error, res);
    }
  }

  // Delete a user (only for ADMIN)
  static deleteUser(req: Request, res: Response) {
    try {
      const userId = parseInt(req.params.id, 10);
      const currentUser = req.user;

      if (currentUser.role !== 'ADMIN') {
        throw new AppError('Forbidden', 403);
      }

      const user = User.findByPk(userId);

      if (!user) {
        throw new AppError('User not found', 404);
      }

      user.destroy();

      res.status(204).send();
    } catch (error) {
      handleError(error, res);
    }
  }
}
```

- **`getAllUsers`:** Checks if the authenticated user's role is `ADMIN`. If not, it throws a `403 Forbidden` error.
- **`getUserById`:** Checks if the authenticated user's role is `USER` and if the `userId` in the request matches the authenticated user's `id`. If not, it throws a `403 Forbidden` error.
- **`updateUser` and `deleteUser`:** Both check if the authenticated user's role is `ADMIN`. If not, a `403 Forbidden` error is thrown. They also verify that the user being updated or deleted exists in the database.

